package com.app.features.promotions.serviceimpl;
import com.app.common.BusinessException;import com.app.features.auth.entity.UserAccount;import com.app.features.auth.security.CurrentUser;import com.app.features.cart.entity.CartItem;import com.app.features.cart.repository.CartItemRepository;import com.app.features.orders.entity.*;import com.app.features.promotions.dto.VoucherDto.*;import com.app.features.promotions.entity.*;import com.app.features.promotions.enums.*;import com.app.features.promotions.repository.*;import com.app.features.promotions.service.VoucherService;import com.app.features.shipping.entity.ShippingZone;import com.app.features.shipping.service.ShippingService;import com.app.features.suppliers.entity.Supplier;import com.app.features.suppliers.repository.SupplierRepository;import java.math.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class VoucherServiceImpl implements VoucherService {
 private final VoucherRepository vouchers;private final VoucherUsageRepository usages;private final OrderVoucherRepository orderVouchers;private final SupplierRepository suppliers;private final CartItemRepository cart;private final CurrentUser current;private final ShippingService shipping;
 public VoucherServiceImpl(VoucherRepository vouchers,VoucherUsageRepository usages,OrderVoucherRepository orderVouchers,SupplierRepository suppliers,CartItemRepository cart,CurrentUser current,ShippingService shipping){this.vouchers=vouchers;this.usages=usages;this.orderVouchers=orderVouchers;this.suppliers=suppliers;this.cart=cart;this.current=current;this.shipping=shipping;}
 @Override @Transactional(readOnly=true) public CheckoutQuote quote(CheckoutQuoteRequest r){return quoteFor(current.get(),r.address(),r.platformVoucherCode(),r.partnerVoucherCodes());}
 @Override @Transactional(readOnly=true) public CheckoutQuote quoteFor(UserAccount user,String address,String platformCode,List<String> partnerCodes){
  List<CartItem> items=cart.findByUserId(user.getId());if(items.isEmpty())throw BusinessException.bad("EMPTY_CART","Giỏ hàng đang trống");Map<Long,List<CartItem>> grouped=new LinkedHashMap<>();items.forEach(i->grouped.computeIfAbsent(i.getProduct().getSupplier().getId(),k->new ArrayList<>()).add(i));BigDecimal subtotal=items.stream().map(this::line).reduce(BigDecimal.ZERO,BigDecimal::add);ShippingZone zone=shipping.resolve(address);BigDecimal shippingFee=shipping.fee(zone,subtotal);
  Map<Long,Voucher> selected=new HashMap<>();for(String code:safe(partnerCodes)){Voucher v=byCode(code);if(v.getScope()!=VoucherScope.PARTNER||v.getSupplier()==null||!grouped.containsKey(v.getSupplier().getId()))throw BusinessException.bad("VOUCHER_SUPPLIER_MISMATCH","Mã "+code+" không áp dụng cho sản phẩm trong giỏ");if(selected.put(v.getSupplier().getId(),v)!=null)throw BusinessException.bad("VOUCHER_LIMIT","Mỗi nhà cung cấp chỉ được áp dụng một voucher");}
  BigDecimal partnerDiscount=BigDecimal.ZERO;List<SupplierDiscount> breakdown=new ArrayList<>();for(var e:grouped.entrySet()){Supplier supplier=e.getValue().get(0).getProduct().getSupplier();BigDecimal sub=e.getValue().stream().map(this::line).reduce(BigDecimal.ZERO,BigDecimal::add);Voucher v=selected.get(e.getKey());BigDecimal d=v==null?BigDecimal.ZERO:discount(validate(v,user,sub),sub);partnerDiscount=partnerDiscount.add(d);breakdown.add(new SupplierDiscount(e.getKey(),supplier.getName(),sub,v==null?null:v.getCode(),d,sub.subtract(d)));}
  BigDecimal afterPartner=subtotal.subtract(partnerDiscount);BigDecimal platformDiscount=BigDecimal.ZERO;if(platformCode!=null&&!platformCode.isBlank()){Voucher v=validate(byCode(platformCode),user,afterPartner);if(v.getScope()!=VoucherScope.PLATFORM)throw BusinessException.bad("VOUCHER_SCOPE_MISMATCH","Voucher này không phải voucher toàn sàn");platformDiscount=discount(v,afterPartner);}
  BigDecimal total=afterPartner.subtract(platformDiscount).add(shippingFee);return new CheckoutQuote(subtotal,partnerDiscount,platformDiscount,shippingFee,BigDecimal.ZERO,total.max(BigDecimal.ZERO),zone.getZoneName(),breakdown,available(user,VoucherScope.PLATFORM,grouped.keySet()),available(user,VoucherScope.PARTNER,grouped.keySet()));
 }
 @Override @Transactional(readOnly=true) public List<VoucherView> minePartner(){Supplier s=ownedSupplier();return vouchers.findBySupplierIdOrderByCreatedAtDesc(s.getId()).stream().map(this::view).toList();}
 @Override @Transactional(readOnly=true) public List<VoucherView> platform(){return vouchers.findByScopeOrderByCreatedAtDesc(VoucherScope.PLATFORM).stream().map(this::view).toList();}
 @Override @Transactional public VoucherView createPartner(VoucherRequest r){Voucher v=new Voucher();v.setScope(VoucherScope.PARTNER);v.setSupplier(ownedSupplier());v.setCreatedBy(current.get());apply(v,r);return view(vouchers.save(v));}
 @Override @Transactional public VoucherView createPlatform(VoucherRequest r){Voucher v=new Voucher();v.setScope(VoucherScope.PLATFORM);v.setCreatedBy(current.get());apply(v,r);return view(vouchers.save(v));}
 @Override @Transactional public VoucherView updatePartner(Long id,VoucherRequest r){Voucher v=ownedPartner(id);apply(v,r);return view(v);}
 @Override @Transactional public VoucherView updatePlatform(Long id,VoucherRequest r){Voucher v=ownedPlatform(id);apply(v,r);return view(v);}
 @Override @Transactional public VoucherView statusPartner(Long id,String s){Voucher v=ownedPartner(id);setStatus(v,s);return view(v);}
 @Override @Transactional public VoucherView statusPlatform(Long id,String s){Voucher v=ownedPlatform(id);setStatus(v,s);return view(v);}
 @Override @Transactional public void reserve(UserAccount user,MarketOrder order,Map<Long,SupplierOrder> parts,CheckoutQuote q,String platformCode){List<String> codes=new ArrayList<>();q.suppliers().stream().map(SupplierDiscount::voucherCode).filter(Objects::nonNull).forEach(codes::add);for(String code:codes)reserveOne(user,order,parts,q,byCode(code));if(platformCode!=null&&!platformCode.isBlank())reserveOne(user,order,parts,q,byCode(platformCode));}
 private void reserveOne(UserAccount user,MarketOrder order,Map<Long,SupplierOrder> parts,CheckoutQuote q,Voucher selected){Voucher v=vouchers.lockById(selected.getId()).orElseThrow(()->BusinessException.missing("Voucher"));BigDecimal amount=v.getScope()==VoucherScope.PLATFORM?q.platformDiscount():q.suppliers().stream().filter(s->Objects.equals(s.supplierId(),v.getSupplier().getId())).findFirst().map(SupplierDiscount::discount).orElse(BigDecimal.ZERO);if(amount.signum()<=0)return;validate(v,user,v.getScope()==VoucherScope.PLATFORM?q.subtotal().subtract(q.partnerDiscount()):q.suppliers().stream().filter(s->Objects.equals(s.supplierId(),v.getSupplier().getId())).findFirst().orElseThrow().subtotal());v.setUsedCount(v.getUsedCount()+1);VoucherUsage u=new VoucherUsage();u.setVoucher(v);u.setUser(user);u.setOrder(order);u.setDiscountAmount(amount);usages.save(u);OrderVoucher ov=new OrderVoucher();ov.setOrder(order);ov.setSupplierOrder(v.getSupplier()==null?null:parts.get(v.getSupplier().getId()));ov.setVoucher(v);ov.setCodeSnapshot(v.getCode());ov.setScopeSnapshot(v.getScope().name());ov.setDiscountTypeSnapshot(v.getDiscountType().name());ov.setDiscountValueSnapshot(v.getDiscountValue());ov.setDiscountAmount(amount);orderVouchers.save(ov);}
 @Override @Transactional public void redeem(Long orderId){usages.findByOrderId(orderId).stream().filter(u->u.getStatus()==VoucherUsageStatus.RESERVED).forEach(u->u.setStatus(VoucherUsageStatus.REDEEMED));}
 @Override @Transactional public void release(Long orderId){for(VoucherUsage u:usages.findByOrderId(orderId)){if(u.getStatus()==VoucherUsageStatus.RESERVED){u.setStatus(VoucherUsageStatus.RELEASED);Voucher v=vouchers.lockById(u.getVoucher().getId()).orElseThrow();v.setUsedCount(Math.max(0,v.getUsedCount()-1));}}}
 private Voucher validate(Voucher v,UserAccount user,BigDecimal base){Instant now=Instant.now();if(v.getStatus()!=VoucherStatus.ACTIVE||!v.isActive()||v.getStartsAt()!=null&&now.isBefore(v.getStartsAt())||v.getExpiresAt()!=null&&now.isAfter(v.getExpiresAt()))throw BusinessException.bad("VOUCHER_NOT_ACTIVE","Voucher không còn hiệu lực");if(v.getMinimumOrderAmount()!=null&&base.compareTo(v.getMinimumOrderAmount())<0)throw BusinessException.bad("VOUCHER_MINIMUM_NOT_MET","Đơn hàng chưa đạt giá trị tối thiểu của voucher");if(v.getUsageLimit()!=null&&v.getUsedCount()>=v.getUsageLimit())throw BusinessException.bad("VOUCHER_USAGE_LIMIT","Voucher đã hết lượt sử dụng");if(usages.countByVoucherIdAndUserIdAndStatusIn(v.getId(),user.getId(),List.of(VoucherUsageStatus.RESERVED,VoucherUsageStatus.REDEEMED))>=1)throw BusinessException.bad("VOUCHER_CUSTOMER_LIMIT","Mỗi tài khoản chỉ được sử dụng mã này một lần");return v;}
 private BigDecimal discount(Voucher v,BigDecimal base){BigDecimal d=v.getDiscountType()==VoucherDiscountType.PERCENTAGE?base.multiply(v.getDiscountValue()).divide(BigDecimal.valueOf(100),2,RoundingMode.DOWN):v.getDiscountValue();if(v.getMaximumDiscountAmount()!=null)d=d.min(v.getMaximumDiscountAmount());return d.min(base).max(BigDecimal.ZERO);}
 private List<VoucherView> available(UserAccount user,VoucherScope scope,Set<Long> supplierIds){return vouchers.findByScopeOrderByCreatedAtDesc(scope).stream().filter(v->scope==VoucherScope.PLATFORM||v.getSupplier()!=null&&supplierIds.contains(v.getSupplier().getId())).filter(v->{try{validate(v,user,BigDecimal.valueOf(Long.MAX_VALUE));return true;}catch(Exception e){return false;}}).map(this::view).toList();}
 private Voucher byCode(String c){return vouchers.findByCodeIgnoreCase(c.trim()).orElseThrow(()->BusinessException.bad("VOUCHER_NOT_FOUND","Không tìm thấy voucher "+c));}private Supplier ownedSupplier(){return suppliers.findByOwnerId(current.get().getId()).orElseThrow(BusinessException::forbidden);}private Voucher ownedPartner(Long id){Voucher v=vouchers.findById(id).orElseThrow(()->BusinessException.missing("Voucher"));if(v.getScope()!=VoucherScope.PARTNER||v.getSupplier()==null||!v.getSupplier().getId().equals(ownedSupplier().getId()))throw BusinessException.forbidden();return v;}private Voucher ownedPlatform(Long id){Voucher v=vouchers.findById(id).orElseThrow(()->BusinessException.missing("Voucher"));if(v.getScope()!=VoucherScope.PLATFORM)throw BusinessException.forbidden();return v;}
 private void apply(Voucher v,VoucherRequest r){if(r.code()==null||!r.code().matches("[A-Za-z0-9_-]{3,80}")||r.name()==null||r.name().isBlank()||r.discountValue()==null||r.discountValue().signum()<=0)throw BusinessException.bad("INVALID_VOUCHER","Thông tin voucher không hợp lệ");VoucherDiscountType type;try{type=VoucherDiscountType.valueOf(r.discountType());}catch(Exception e){throw BusinessException.bad("INVALID_VOUCHER_TYPE","Loại giảm giá không hợp lệ");}if(type==VoucherDiscountType.PERCENTAGE&&r.discountValue().compareTo(BigDecimal.valueOf(100))>0)throw BusinessException.bad("INVALID_VOUCHER_VALUE","Phần trăm giảm không được vượt quá 100");if(r.startsAt()!=null&&r.expiresAt()!=null&&!r.expiresAt().isAfter(r.startsAt()))throw BusinessException.bad("INVALID_VOUCHER_TIME","Thời gian kết thúc phải sau thời gian bắt đầu");v.setCode(r.code().trim().toUpperCase(Locale.ROOT));v.setName(r.name().trim());v.setDescription(r.description());v.setDiscountType(type);v.setDiscountValue(r.discountValue());v.setMaximumDiscountAmount(r.maximumDiscountAmount());v.setMinimumOrderAmount(r.minimumOrderAmount());v.setUsageLimit(r.usageLimit());v.setPerCustomerLimit(1);v.setStartsAt(r.startsAt());v.setExpiresAt(r.expiresAt());v.setNewCustomerOnly(false);if(r.status()!=null)setStatus(v,r.status());}
 private void setStatus(Voucher v,String s){try{VoucherStatus status=VoucherStatus.valueOf(s.toUpperCase(Locale.ROOT));v.setStatus(status);v.setActive(status==VoucherStatus.ACTIVE);}catch(Exception e){throw BusinessException.bad("INVALID_VOUCHER_STATUS","Trạng thái voucher không hợp lệ");}}
 private VoucherView view(Voucher v){return new VoucherView(v.getId(),v.getCode(),v.getName(),v.getDescription(),v.getScope().name(),v.getDiscountType().name(),v.getDiscountValue(),v.getMaximumDiscountAmount(),v.getMinimumOrderAmount(),v.getUsageLimit(),v.getUsedCount(),v.getPerCustomerLimit(),v.getStartsAt(),v.getExpiresAt(),v.getStatus().name(),v.getSupplier()==null?null:v.getSupplier().getId(),v.getSupplier()==null?null:v.getSupplier().getName(),v.isNewCustomerOnly());}private BigDecimal line(CartItem i){return i.getProduct().getPrice().multiply(i.getQuantity());}private List<String> safe(List<String> l){return l==null?List.of():l.stream().filter(s->s!=null&&!s.isBlank()).toList();}
}
